// UnknownEvent 是 SDK 尚未识别的事件，保留原始 JSON。
type UnknownEvent struct {
	EventMeta

	// Type 是协议端给出的事件类型。
	Type EventType
	// Raw 是原始事件 JSON。
	Raw json.RawMessage
}

// EventType 返回原始事件类型。
func (e *UnknownEvent) EventType() EventType { return e.Type }

// Meta 返回事件公共元信息。
func (e *UnknownEvent) Meta() EventMeta { return e.EventMeta }

func (e *UnknownEvent) event() {}

// MarshalJSON 原样回填未知事件。
func (e *UnknownEvent) MarshalJSON() ([]byte, error) { return e.Raw, nil }

// UnmarshalEvent 按 event_type 解码事件；未知类型返回 *UnknownEvent。
func UnmarshalEvent(b []byte) (Event, error) {
	tag, err := jsonx.TaggedPeek(b, "event_type")
	if err != nil {
		return nil, err
	}
	var ev Event
	switch EventType(tag) {
	case EventBotOffline:
		ev = new(BotOfflineEvent)
	case EventMessageReceive:
		ev = new(MessageReceiveEvent)
	case EventMessageRecall:
		ev = new(MessageRecallEvent)
	case EventPeerPinChange:
		ev = new(PeerPinChangeEvent)
	case EventFriendRequest:
		ev = new(FriendRequestEvent)
	case EventGroupJoinRequest:
		ev = new(GroupJoinRequestEvent)
	case EventGroupInvitedJoinRequest:
		ev = new(GroupInvitedJoinRequestEvent)
	case EventGroupInvitation:
		ev = new(GroupInvitationEvent)
	case EventFriendNudge:
		ev = new(FriendNudgeEvent)
	case EventFriendFileUpload:
		ev = new(FriendFileUploadEvent)
	case EventGroupAdminChange:
		ev = new(GroupAdminChangeEvent)
	case EventGroupEssenceMessageChange:
		ev = new(GroupEssenceMessageChangeEvent)
	case EventGroupMemberIncrease:
		ev = new(GroupMemberIncreaseEvent)
	case EventGroupMemberDecrease:
		ev = new(GroupMemberDecreaseEvent)
	case EventGroupDisband:
		ev = new(GroupDisbandEvent)
	case EventGroupNameChange:
		ev = new(GroupNameChangeEvent)
	case EventGroupMessageReaction:
		ev = new(GroupMessageReactionEvent)
	case EventGroupMute:
		ev = new(GroupMuteEvent)
	case EventGroupWholeMute:
		ev = new(GroupWholeMuteEvent)
	case EventGroupNudge:
		ev = new(GroupNudgeEvent)
	case EventGroupFileUpload:
		ev = new(GroupFileUploadEvent)
	default:
		var meta struct{ EventMeta }
		if err := json.Unmarshal(b, &meta); err != nil {
			return nil, fmt.Errorf("types: 解码未知事件元信息失败: %w", err)
		}
		return &UnknownEvent{EventMeta: meta.EventMeta, Type: EventType(tag), Raw: append(json.RawMessage(nil), b...)}, nil
	}
	if err := json.Unmarshal(b, ev); err != nil {
		return nil, fmt.Errorf("types: 解码 %q 事件失败: %w", tag, err)
	}
	return ev, nil
}
